import React from "react";
import { Link, useLocation } from "react-router-dom";
import { FaHeart, FaShoppingCart } from "react-icons/fa";
import SearchBar from "../SearchBar/SearchBar";

export default function Navbar() {
  const location = useLocation();

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="navbar navbar-expand-lg bg-white shadow-sm sticky-top">
      <div className="container d-flex align-items-center justify-content-between">
        {/* ====== Logo ====== */}
        <Link className="navbar-brand fw-bold text-danger fs-4" to="/">
          Exsclusive
        </Link>

        {/* ====== Toggle Button (Mobile) ====== */}
        <button
          className="navbar-toggler border-0"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#mainNav"
          aria-controls="mainNav"
          aria-expanded="false"
          aria-label="Toggle navigation"
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        {/* ====== Center Search Bar ====== */}
        <div className="d-none d-lg-flex flex-grow-1 justify-content-center mx-3">
          <div style={{ width: "100%", maxWidth: "500px" }}>
            <SearchBar />
          </div>
        </div>

        {/* ====== Links & Icons ====== */}
        <div className="collapse navbar-collapse justify-content-end" id="mainNav">
          <ul className="navbar-nav align-items-lg-center mb-2 mb-lg-0 gap-3 text-center">
            <li className="nav-item">
              <Link
                to="/"
                className={`nav-link fw-semibold ${
                  isActive("/") ? "text-danger" : "text-dark"
                }`}
              >
                Home
              </Link>
            </li>
            <li className="nav-item">
              <Link
                to="/contact"
                className={`nav-link fw-semibold ${
                  isActive("/contact") ? "text-danger" : "text-dark"
                }`}
              >
                Contact
              </Link>
            </li>
            <li className="nav-item">
              <Link
                to="/about"
                className={`nav-link fw-semibold ${
                  isActive("/about") ? "text-danger" : "text-dark"
                }`}
              >
                About
              </Link>
            </li>
            <li className="nav-item">
              <Link
                to="/login"
                className={`nav-link fw-semibold ${
                  isActive("/login") ? "text-danger" : "text-dark"
                }`}
              >
                Sign Up / Login
              </Link>
            </li>

            {/* ====== Mobile SearchBar ====== */}
            <li className="nav-item d-lg-none mt-2 mb-3">
              <div style={{ width: "100%" }}>
                <SearchBar />
              </div>
            </li>

            {/* ====== Icons ====== */}
            <li className="nav-item d-flex justify-content-center gap-3">
              <Link
                to="/wishList"
                className="position-relative text-decoration-none text-dark"
              >
                <FaHeart size={20} />
                <span
                  className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                  style={{ fontSize: 10 }}
                >
                  3
                </span>
              </Link>

              <Link
                to="/cart"
                className="position-relative text-decoration-none text-dark"
              >
                <FaShoppingCart size={20} />
                <span
                  className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                  style={{ fontSize: 10 }}
                >
                  2
                </span>
              </Link>
            </li>
          </ul>
        </div>
      </div>
    </nav>
  );
}
